449	        else if (FUS[`FU_ALU][`RDY1] & FUS[`FU_ALU][`RDY2]) begin
450	            ALU_en = 1'b1;
451	            MEM_en = 1'b0;
452	            MUL_en = 1'b0;
453	            DIV_en = 1'b0;
454	            JUMP_en = 1'b0;
455	
456	            ALU_op = FUS[`FU_ALU][`OP_H:`OP_L] == `ALU_AUIPC ? 
457	                      4'b0001 : FUS[`FU_ALU][`OP_L+3:`OP_L];
458	            rs1_ctrl = FUS[`FU_ALU][`SRC1_H:`SRC1_L];
459	            rs2_ctrl = FUS[`FU_ALU][`SRC2_H:`SRC2_L];
