501	        end
502	    end
503	
504	    // WB
505	    always @ (*) begin
506	        write_sel = 0;
507	        reg_write = 0;
508	        rd_ctrl = 0;
509	
510	        if (FUS[`FU_JUMP][`FU_DONE] & JUMP_WAR) begin
