1	`timescale 1ns / 1ps
2	
3	module FU_jump(
4		input clk, EN, JALR,
5		input[3:0] cmp_ctrl,
6		input[31:0] rs1_data, rs2_data, imm, PC,
7		output[31:0] PC_jump, PC_wb,
8		output is_jump, finish
9	);
10	
11		wire cmp_res;
12	    reg state;
13	    assign finish = state == 1'b1;
14		initial begin
15	        state = 0;
16	    end
17	
18	    reg JALR_reg;
19	    reg[3:0] cmp_ctrl_reg;
20	    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg, PC_reg;
21	
22	    // latch inputs on EN, one-cycle result
23	    always @(posedge clk) begin
24	        if (EN & ~state) begin
25	            JALR_reg <= JALR;
26	            cmp_ctrl_reg <= cmp_ctrl;
27	            rs1_data_reg <= rs1_data;
28	            rs2_data_reg <= rs2_data;
29	            imm_reg <= imm;
30	            PC_reg <= PC;
31	            state <= 1'b1;
32	        end
33	        else if (state) begin
34	            state <= 1'b0;
35	        end
36	    end
37	
38	    cmp_32 cmp(.a(rs1_data_reg), .b(rs2_data_reg),
39	        .ctrl(cmp_ctrl_reg[3:1]), .c(cmp_res));
40	
41	    // JALR: target = rs1 + imm; JAL/branch: target = PC + imm
42	    wire[31:0] base = JALR_reg ? rs1_data_reg : PC_reg;
43	    add_32 add_target(.a(base), .b(imm_reg), .c(PC_jump));
44	    add_32 add_return(.a(PC_reg), .b(32'd4), .c(PC_wb));
45	
46	    // unconditional jump or condition met
47	    assign is_jump = cmp_ctrl_reg[0] | cmp_res;
48	
49	endmodule

1	`timescale 1ns / 1ps
2	
3	module FU_mul(
4	    input clk, EN,
5	    input[31:0] A, B,
6	    output[31:0] res,
7	    output finish
8	);
9	
10	    reg[6:0] state;
11	    assign finish = state[0] == 1'b1;
12	    initial begin
13	        state = 0;
14	    end
15	
16	    reg[31:0] A_reg, B_reg;
17	
18	    // 64-cycle latency: 7'b100_0000 -> ... -> 7'b000_0001 -> 7'b000_0000
19	    always @(posedge clk) begin
20	        if (EN & ~|state) begin
21	            A_reg <= A;
22	            B_reg <= B;
23	            state <= 7'b100_0000;
24	        end
25	        else begin
26	            state <= {1'b0, state[6:1]};
27	        end
28	    end
29	
30	    wire[63:0] mulres;
31	    multiplier mul(.CLK(clk), .A(A_reg), .B(B_reg), .P(mulres));
32	
33	    assign res = mulres[31:0];
34	
35	endmodule

1	`timescale 1ns / 1ps
2	
3	module FU_div(
4	    input clk, EN,
5	    input[31:0] A, B,
6	    output[31:0] res,
7	    output finish
8	);
9	
10	    wire res_valid;
11	    wire[63:0] divres;
12	    
13	    reg state;
14	    assign finish = res_valid & state;
15	    initial begin
16	        state = 0;
17	    end
18	
19	    reg A_valid, B_valid;
20	    reg[31:0] A_reg, B_reg;
21	    initial begin
22	        A_valid = 0;
23	        B_valid = 0;
24	    end
25	
26	    // AXI-style handshake: raise valid for one cycle when EN,
27	    // then wait until the divider raises res_valid.
28	    always @(posedge clk) begin
29	        if (EN & ~state) begin
30	            A_reg <= A;
31	            B_reg <= B;
32	            A_valid <= 1'b1;
33	            B_valid <= 1'b1;
34	            state <= 1'b1;
35	        end
36	        else if (res_valid) begin
37	            A_valid <= 1'b0;
38	            B_valid <= 1'b0;
39	            state <= 1'b0;
40	        end
41	        else begin
42	            A_valid <= 1'b0;
43	            B_valid <= 1'b0;
44	        end
45	    end
46	
47	    divider div(
48	        .aclk(clk),
49	        .s_axis_dividend_tvalid(A_valid),
50	        .s_axis_dividend_tdata(A_reg),
51	        .s_axis_divisor_tvalid(B_valid),
52	        .s_axis_divisor_tdata(B_reg),
53	        .m_axis_dout_tvalid(res_valid),
54	        .m_axis_dout_tdata(divres)
55	    );
56	
57	    // quotient is in the upper 32 bits of the result bus
58	    assign res = divres[63:32];
59	
60	endmodule

1	`timescale 1ns / 1ps
2	
3	module FU_mem(
4	    input clk, EN, mem_w,
5	    input[2:0] bhw,
6	    input[31:0] rs1_data, rs2_data, imm,
7	    output[31:0] mem_data,
8	    output finish
9	);
10	
11	    reg[1:0] state;
12	    assign finish = state[0] == 1'b1;
13	    initial begin
14	        state = 0;
15	    end
16	
17	    reg mem_w_reg;
18	    reg[2:0] bhw_reg;
19	    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg;
20	
21	    // 2-cycle latency: 2'b10 -> 2'b01 -> 2'b00
22	    always @(posedge clk) begin
23	        if (EN & ~|state) begin
24	            mem_w_reg <= mem_w;
25	            bhw_reg <= bhw;
26	            rs1_data_reg <= rs1_data;
27	            rs2_data_reg <= rs2_data;
28	            imm_reg <= imm;
29	            state <= 2'b10;
30	        end
31	        else begin
32	            state <= {1'b0, state[1]};
33	        end
34	    end
35	
36	    wire[31:0] addr;
37	    add_32 add_addr(.a(rs1_data_reg), .b(imm_reg), .c(addr));
38	
39	    RAM_B ram(.addra(addr), .clka(clk), .dina(rs2_data_reg),
40	        .wea(mem_w_reg & (|state)), .douta(mem_data), .mem_u_b_h_w(bhw_reg));
41	
42	endmodule

1	`timescale 1ns / 1ps
2	
3	// Behavioral model of the divider IP (Vivado div_gen compatible interface).
4	// Signed 32-bit division; m_axis_dout_tdata = {quotient, remainder}.
5	module divider(
6	    input aclk,
7	    input s_axis_dividend_tvalid,
8	    input[31:0] s_axis_dividend_tdata,
9	    input s_axis_divisor_tvalid,
10	    input[31:0] s_axis_divisor_tdata,
11	    output reg m_axis_dout_tvalid,
12	    output reg[63:0] m_axis_dout_tdata
13	);
14	
15	    reg[31:0] dividend, divisor;
16	    reg[5:0] count;
17	    reg busy;
18	
19	    initial begin
20	        m_axis_dout_tvalid = 1'b0;
21	        m_axis_dout_tdata = 64'b0;
22	        busy = 1'b0;
23	        count = 6'b0;
24	    end
25	
26	    always @(posedge aclk) begin
27	        if (m_axis_dout_tvalid) begin
28	            m_axis_dout_tvalid <= 1'b0;     // result valid for one cycle
29	        end
30	
31	        if (~busy & s_axis_dividend_tvalid & s_axis_divisor_tvalid) begin
32	            dividend <= s_axis_dividend_tdata;
33	            divisor <= s_axis_divisor_tdata;
34	            busy <= 1'b1;
35	            count <= 6'd0;
36	        end
37	        else if (busy) begin
38	            if (count == 6'd32) begin
39	                busy <= 1'b0;
40	                m_axis_dout_tvalid <= 1'b1;
41	                if (divisor == 32'b0) begin
42	                    // RISC-V division by zero: q = -1, r = dividend
43	                    m_axis_dout_tdata <= {32'hFFFF_FFFF, dividend};
44	                end
45	                else begin
46	                    m_axis_dout_tdata <= {$signed(dividend) / $signed(divisor),
47	                                          $signed(dividend) % $signed(divisor)};
48	                end
49	            end
50	            else begin
51	                count <= count + 6'd1;
52	            end
53	        end
54	    end
55	
56	endmodule

