`timescale 1ns / 1ps
// Testbench for lab5 scoreboard CPU (OoO, RV32IM).
// Instantiates RV32core directly, runs the pre-loaded rom.mem program
// (see lab5/ref/inst.S) and checks every WB-stage register write:
//   - no X/Z on RegWrite_ctrl / rd_ctrl / wt_data_WB when RegWrite_ctrl=1
//   - per-register write streams match the hand-executed expected values
//     (per-register order is architecturally guaranteed by the WAW stall,
//      even though the scoreboard retires instructions out of order)
//   - only registers x1,x2,x4,x5,x6,x7,x8,x9 (and harmless x0) are written
//   - the program keeps making progress (it loops via jalr to PC=0)
//
// Run vvp from lab5/core so ROM_D/RAM_B find rom.mem/ram.mem.

module tb_rv32core;

    reg clk = 0;
    reg rst = 1;
    always #5 clk = ~clk;   // 100MHz

    wire [31:0] wb_addr, wb_data, clk_counter, debug_data;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(debug_data),
        .wb_addr(wb_addr),
        .wb_data(wb_data),
        .clk_counter(clk_counter),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    // hierarchical handles to the WB-stage signals inside RV32core
    wire        RegWrite_WB = core.RegWrite_ctrl;
    wire [4:0]  rd_WB       = core.rd_ctrl;
    wire [31:0] wt_data_WB  = core.wt_data_WB;
    wire [2:0]  write_sel   = core.DatatoReg_ctrl;

    integer errors = 0;
    integer writes = 0;        // writes with rd != 0
    integer idx [1:31];        // per-register stream position

    // expected per-register value streams (one program iteration each,
    // they repeat because jalr x1,0(x0) restarts the program at PC=0)
    // x1: 18, 17, 8, fffffffd, 00004000, 00000048, ffff0050, 00000068
    // x2: 00000008, 00000004
    // x4: 00000010   x5: 00000014   x6: ffff0000   x7: 0fff0000
    // x8: 01ffe000
    // x9: 00000140, 0fff0000
    reg [31:0] exp_val;
    reg [31:0] dummy;

    task expect_write(input [4:0] rd, input [31:0] data);
        integer i;
        begin
            i = idx[rd];
            case (rd)
                1: case (i % 8)
                        0: exp_val = 32'h00000018;
                        1: exp_val = 32'h00000017;
                        2: exp_val = 32'h00000008;
                        3: exp_val = 32'hfffffffd;
                        4: exp_val = 32'h00004000;
                        5: exp_val = 32'h00000048;
                        6: exp_val = 32'hffff0050;
                        7: exp_val = 32'h00000068;
                   endcase
                2: exp_val = (i % 2 == 0) ? 32'h00000008 : 32'h00000004;
                4: exp_val = 32'h00000010;
                5: exp_val = 32'h00000014;
                6: exp_val = 32'hffff0000;
                7: exp_val = 32'h0fff0000;
                8: exp_val = 32'h01ffe000;
                9: exp_val = (i % 2 == 0) ? 32'h00000140 : 32'h0fff0000;
                default: exp_val = 32'hxxxxxxxx;
            endcase
            if (rd != 1 && rd != 2 && rd != 4 && rd != 5 &&
                rd != 6 && rd != 7 && rd != 8 && rd != 9) begin
                $display("ERROR @%0t: unexpected write to x%0d data=%h", $time, rd, data);
                errors = errors + 1;
            end
            else if (data !== exp_val) begin
                $display("ERROR @%0t: x%0d = %h, expected %h (stream idx %0d)",
                         $time, rd, data, exp_val, i);
                errors = errors + 1;
            end
            idx[rd] = i + 1;
            writes = writes + 1;
        end
    endtask

    integer cyc = 0;
    integer k;

    initial begin
        for (k = 0; k < 32; k = k + 1) idx[k] = 0;
        // hold reset for a few cycles
        repeat (5) @(posedge clk);
        #1 rst = 0;

        // run long enough for several program iterations
        // (one iteration is ~120 cycles; div ~35 cycles, mul ~9 cycles)
        repeat (1200) @(posedge clk);

        $display("--------------------------------------------------");
        $display("cycles run: %0d, WB writes (rd!=0): %0d, errors: %0d", cyc, writes, errors);
        if (writes < 51) begin
            $display("ERROR: too few WB writes, program not making progress");
            errors = errors + 1;
        end
        if (errors == 0) $display("TEST PASSED");
        else             $display("TEST FAILED (%0d errors)", errors);
        $finish;
    end

    // sample WB stage once per cycle (just before the posedge that ends it)
    always @(negedge clk) begin
        if (!rst) begin
            cyc = cyc + 1;
            // X/Z checks on the WB control/data signals
            if (RegWrite_WB === 1'bx || RegWrite_WB === 1'bz) begin
                $display("ERROR @%0t: RegWrite_ctrl is %b", $time, RegWrite_WB);
                errors = errors + 1;
            end
            else if (RegWrite_WB) begin
                if (^rd_WB === 1'bx || ^wt_data_WB === 1'bx) begin
                    $display("ERROR @%0t: X/Z in WB write: rd=%b data=%b",
                             $time, rd_WB, wt_data_WB);
                    errors = errors + 1;
                end
                else begin
                    $display("cyc %4d: WB x%0d <- %h (write_sel=%0d)",
                             cyc, rd_WB, wt_data_WB, write_sel);
                    if (rd_WB != 0) expect_write(rd_WB, wt_data_WB);
                end
            end
        end
    end

endmodule
